/* Super Admin modules C: Certificates, Agencies, Bundles, Referrals, Finance, Reports, Announcements, Messages,
   Notification Settings, Data Protection, Audit & Security, Integrations, System Configuration, My Profile, admin screen index */
'use strict';

/* ---------- 6.16 Certificates ---------- */
function allCerts() {
  const out = [];
  [...'ABCDEF'].forEach(v => STORE.worlds[v].certs.forEach(c => out.push({ key: v + ':' + c.id, v, c, no: c.no, learner: VNAME(v), course: c.course, issued: c.issued, expires: c.expires, status: c.status, tpl: 'v' + (c.supersedes ? 3 : 2), sponsor: STORE.worlds[v].me.sponsor || '—', lineage: !!c.supersedes })));
  if (!fxClient()) [['WEL-2026-02310', 'Kofi Asante', 'Moving and Handling People', D(-30), D(335), 'Valid', 'BrightCare Staffing Ltd (demo)'], ['WEL-2025-01980', 'Isla Morgan', 'Fire Safety Awareness', D(-370), D(-5), 'Expired', 'CarePlus Recruitment (demo)'], ['WEL-2026-02101', 'Anjali Nair', 'Dementia Awareness', D(-60), D(670), 'Valid', '—'], ['WEL-2026-01650', 'Maria Santos', 'Basic Life Support and Anaphylaxis', D(-340), D(25), 'Expiring soon', 'Gulf Care Recruitment (demo)']].forEach((r, k) => out.push({ key: 'X:' + k, no: r[0], learner: r[1], course: r[2], issued: r[3], expires: r[4], status: r[5], tpl: 'v2', sponsor: r[6], lineage: false, c: { no: r[0], status: r[5] } }));
  return out;
}
SCREENS['a-certificates'] = (p) => {
  if (p.id) return certDetail(p.id);
  const t = p.tab || 'register';
  const errs = ADMIN.certErrors = ADMIN.certErrors || [{ id: 'CG-41', learner: 'Daniel Okafor', course: 'Dementia Awareness', at: D(0, '07:41'), err: 'Template render timeout', v: 'A', cid: 'c6' }, { id: 'CG-40', learner: 'Fatima Al Mansoori', course: 'Dementia Awareness', at: D(-1, '12:10'), err: 'QR service unavailable', v: 'F', cid: 'c6' }];
  const st = subtabs([['register', 'Register'], ['errors', `Generation errors (${errs.length})`]], t, 'a-certificates');
  if (t === 'errors') return pageA('Certificates') + st + (errs.length ? `<section class="card"><ul class="list">${errs.map(e => `<li class="li"><div class="li-b"><strong>${esc(e.learner)} · ${esc(e.course)}</strong><span class="small" style="color:var(--red)">${esc(e.err)}</span><span class="xs muted">${e.id} · ${fdt(e.at)}</span></div><button class="btn btn-sm btn-primary" data-act="certRetry" data-id="${e.id}">${ic('refresh', 14)}Retry</button></li>`).join('')}</ul></section>` : `<div class="card"><div class="empty">${ic('check', 30)}<p>No generation errors.</p></div></div>`);
  return pageA('Certificates', 'Issued by Welfare on behalf of Illumin Academy') + st + dt({ id: 'certs', name: 'Certificate register', rows: allCerts(), rid: c => c.key, search: c => c.no + c.learner + c.course, filters: [{ k: 's', l: 'Status', get: c => c.status, opts: ['Valid', 'Expiring soon', 'Expired', 'Revoked', 'Processing'] }, { k: 'sp', l: 'Sponsor', get: c => c.sponsor }],
    cols: [{ k: 'no', l: 'Certificate no.', h: c => `<a href="#a-certificates.${encodeURIComponent(c.key).replace(/%3A/, '~')}" data-go="a-certificates" data-id="${c.key.replace(':', '~')}" class="mono">${c.no}</a>` }, { k: 'learner', l: 'Learner' }, { k: 'course', l: 'Course' }, { k: 'issued', l: 'Issued', h: c => c.issued ? fd(c.issued) : '—', s: c => c.issued || '' }, { k: 'expires', l: 'Expiry', h: c => c.expires ? fd(c.expires) : 'No expiry', s: c => c.expires || '9' }, { k: 'status', l: 'Status', h: c => chip(c.status) }, { k: 'tpl', l: 'Template' }, { k: 'sponsor', l: 'Sponsor', hide: 1 }, { k: 'lin', l: 'Lineage', h: c => c.lineage ? chip('Re-issued', 'teal') : '—' }],
    act: c => `<button class="btn btn-sm" data-go="a-certificates" data-id="${c.key.replace(':', '~')}">Open</button>` });
};
function certByKey(k) { return allCerts().find(c => c.key === k.replace('~', ':')); }
function certDetail(k) {
  const x = certByKey(k); if (!x) return notFound(); const c = x.c;
  return `${pageA('Certificate ' + x.no, `${esc(x.learner)} · ${esc(x.course)}`, chip(x.status), [['Certificates', 'a-certificates'], [x.no]])}
  <div class="grid-2"><section class="card"><div class="cert-doc" style="padding:24px"><span class="w-brand">Welfare</span><h3>Certificate of completion</h3><span class="nm">${esc(x.learner)}</span><p>${esc(x.course)}</p><div class="meta"><span>Issued ${x.issued ? fd(x.issued) : '—'}<br>${x.expires ? 'Valid until ' + fd(x.expires) : 'No expiry'}</span>${qr(x.no, 56)}<span>${x.no}</span></div></div></section>
  <section class="card"><h2>Actions</h2><div class="stack">${x.status !== 'Revoked' && x.v ? `<button class="btn btn-danger" data-act="revokeCert" data-k="${x.key}">Revoke</button>` : ''}${x.v ? `<button class="btn" data-act="raiseDC" data-id="${STORE.worlds[x.v].me.id}">Re-issue (via Data Correction)</button>` : ''}<button class="btn" data-act="aCopyVerify" data-n="${x.no}">${ic('copy', 15)}Copy verification link</button></div>
  <h3>Lineage</h3>${c.lineage ? `<ol class="tl">${c.lineage.map((l, i) => `<li class="${i === c.lineage.length - 1 ? 'cur' : 'done'}"><span class="tl-d">${i + 1}</span><div class="small"><span class="mono">${l[0]}</span> · ${fd(l[1])}<br><span class="muted">${l[2]}</span></div></li>`).join('')}</ol>` : '<p class="small muted">Original certificate — no re-issues.</p>'}
  ${c.revoked ? `<div class="reason"><span class="r-t">Revoked</span><span>${esc(c.revoked)}</span></div>` : ''}</section></div>${auditPanel(a => a.entity.includes(x.no))}`;
}
ACT.revokeCert = el => { const [v, id] = el.dataset.k.split(':'), c = STORE.worlds[v].certs.find(x => x.id === id); reasonDlg({ title: 'Revoke certificate ' + c.no, ok: 'Revoke certificate', danger: true, body: '<p class="small">The verification page will report this certificate as Revoked. It is never deleted.</p>', onOk: r => { const b = c.status; c.status = 'Revoked'; c.revoked = 'Revoked on ' + fd(now().toISOString()) + ': ' + r; notifyLearner(v, 'Certificates', 'Certificate revoked', `${c.course} certificate was revoked.`, 'certificates'); logA('Certificates', c.no, 'Revoked', b, 'Revoked', r); render(); toast('Certificate revoked. The learner sees it as Revoked.'); } }); };
ACT.aCopyVerify = el => copyText('https://welfare-verify.example/' + el.dataset.n, 'Verification link copied');
ACT.certRetry = el => { const e = ADMIN.certErrors.find(x => x.id === el.dataset.id); if (ADMIN.edge === 'certFail') { toast('Retry failed: template render timeout. Try again later.', 'err'); return; } const c = STORE.worlds[e.v].certs.find(x => x.id === e.cid); if (c && c.status === 'Processing') { c.status = 'Valid'; c.no = 'WEL-2026-0' + (2500 + ADMIN.certErrors.length); c.issued = now().toISOString(); c.expires = D(730); notifyLearner(e.v, 'Certificates', 'Certificate issued', c.course + ' certificate is ready.', 'certificates'); } ADMIN.certErrors = ADMIN.certErrors.filter(x => x !== e); logA('Certificates', e.id, 'Generation retried', 'Failed', 'Issued', ''); render(); toast('Certificate generated.'); };

/* ---------- 6.17 Agencies ---------- */
const agencyLearners = name => allLearners().filter(l => l.agency === name);
SCREENS['a-agencies'] = (p) => {
  if (p.id) return agencyDetail(p.id, p.tab || 'profile');
  const t = ui('agTab', 'list');
  return `${pageA('Agencies', '', `<button class="btn btn-primary" data-act="newAgency">${ic('plus', 15)}Create agency</button>`)}
  <div class="note b-grey">${ic('shield')}<div class="small"><strong>One agency can never see another's data.</strong></div></div>
  ${tabs([['list', 'Agencies'], ['all', 'All-agencies report']], t, 'agTab')}
  ${t === 'all' ? agencyReport(null) : dt({ id: 'agencies', name: 'Agencies', rows: ADMIN.agencies, cols: [{ k: 'name', l: 'Agency', h: a => `<a href="#a-agencies.${a.id}" data-go="a-agencies" data-id="${a.id}" class="strong">${esc(a.name)}</a>` }, { k: 'region', l: 'Region' }, { k: 'contact', l: 'Contact', h: a => `<span class="small">${esc(a.contact)}</span>` }, { k: 'act', l: 'Active learners', r: 1, v: a => agencyLearners(a.name).length }, { k: 'bundles', l: 'Bundles', r: 1, v: a => ADMIN.bundles.filter(b => b.agency === a.name).length }, { k: 'seats', l: 'Seats (total/used/remaining)', h: a => { const bs = ADMIN.bundles.filter(b => b.agency === a.name); const t_ = bs.reduce((x, b) => x + b.seats, 0), u = bs.reduce((x, b) => x + b.used, 0); return `${t_} / ${u} / <strong>${t_ - u}</strong>`; } }, { k: 'status', l: 'Status', h: a => chip(a.status, a.status === 'Active' ? 'green' : 'amber') }], act: a => `<button class="btn btn-sm" data-go="a-agencies" data-id="${a.id}">Open</button>` })}`;
};
ACT.agTab = el => { setUi('agTab', el.dataset.k); render(); };
ACT.newAgency = () => openModal({ title: 'Create agency', size: 'lg', body: `<div class="form-grid"><div class="field full"><label for="na-n">Organisation name</label><input class="input" id="na-n"></div><div class="field"><label for="na-r">Region</label><select class="select" id="na-r"><option>UK</option><option>UAE</option></select></div><div class="field"><label for="na-c">Main contact</label><input class="input" id="na-c"></div><div class="field"><label for="na-p">Communication permissions</label><select class="select" id="na-p"><option>Full</option><option>Receive-only</option></select></div><div class="field"><label for="na-e">Agency Administrator login email</label><input class="input" id="na-e" type="email"><span class="hint">One login per agency.</span></div></div>`, actions: [{ label: 'Cancel' }, { label: 'Create and send set-password link', cls: 'btn-primary', fn: () => { const n = mval('#na-n'), e = mval('#na-e'); if (!n) { fieldErr('#na-n', 'Enter the organisation name'); return false; } if (!/^\S+@\S+\.\S+$/.test(e)) { fieldErr('#na-e', 'Enter a valid email'); return false; } const id = 'AG-0' + (ADMIN.agencies.length + 1); ADMIN.agencies.push({ id, name: n, region: mval('#na-r'), contact: mval('#na-c'), email: e, status: 'Active', perms: mval('#na-p'), vis: { individual: true, consolidated: true, assessment: false, attendance: true, payments: false, certExpiry: true }, login: e, loginStatus: 'Pending' }); logA('Agencies', n, 'Agency created', '—', 'Active', ''); toast(`Agency created. Set-password link sent to ${esc(e)}.`); go('a-agencies', { id }); } }] });
function agencyReport(a) {
  const L = a ? agencyLearners(a.name) : allLearners().filter(l => l.agency);
  const vis = a ? a.vis : { individual: true, consolidated: true, assessment: true, certExpiry: true };
  return `<div class="kpis">${kpi('Total learners', L.length)}${kpi('Completion rate', a ? '76%' : '72%')}${kpi('Expiring certificates', a ? 2 : 7)}</div>
  <div class="row"><select class="select" style="width:auto" aria-label="Report type"><option>Consolidated (all students)</option><option>Individual student report</option></select>${exportMenu((a ? a.name : 'All agencies') + ' report')}</div>
  <div class="tbl-wrap"><table class="tbl dense"><thead><tr><th>Learner</th>${a ? '' : '<th>Agency</th>'}<th>Courses</th><th>Progress</th>${vis.assessment ? '<th>Pass / Fail</th>' : ''}${vis.certExpiry ? '<th>Cert expiry</th>' : ''}</tr></thead><tbody>${L.map((l, k) => `<tr><td>${esc(l.name)}</td>${a ? '' : `<td class="small">${esc(l.agency)}</td>`}<td class="small">${esc(l.courses.join('; '))}</td><td>${40 + k * 7 % 55}%</td>${vis.assessment ? `<td class="small">${k % 2 ? '1 resubmission' : 'On track'}</td>` : ''}${vis.attendance ? `<td>${80 + k % 15}%</td>` : ''}${vis.certExpiry ? `<td>${fd(D(20 + k * 30))}</td>` : ''}</tr>`).join('')}</tbody></table></div>`;
}
function agencyDetail(id, t) {
  const a = ADMIN.agencies.find(x => x.id === id); if (!a) return notFound();
  const visLbl = { individual: 'Individual student report', consolidated: 'Consolidated report', assessment: 'Pass / Fail result', certExpiry: 'Certificate expiry column' };
  const body = {
    profile: `<section class="card"><dl class="kv"><dt>Region</dt><dd>${a.region}</dd><dt>Contact</dt><dd>${esc(a.contact)}</dd><dt>Email</dt><dd>${esc(a.email)}</dd><dt>Communication</dt><dd>${a.perms}</dd></dl></section>`,
    login: `<section class="card"><p>Agency Administrator login: <strong>${esc(a.login)}</strong> ${chip(a.loginStatus, a.loginStatus === 'Active' ? 'green' : 'red')}</p><p class="small muted">One login per agency.</p><div class="row"><button class="btn btn-sm" data-act="agLogin" data-id="${a.id}" data-a="resend">Resend set-password link</button><button class="btn btn-sm" data-act="agLogin" data-id="${a.id}" data-a="email">Change email</button><button class="btn btn-sm btn-danger" data-act="agLogin" data-id="${a.id}" data-a="deactivate">Deactivate login</button></div></section>`,
    visibility: `<div class="grid-2"><section class="card"><h2>Report visibility</h2><p class="small muted">Applies immediately.</p><ul class="list">${Object.entries(visLbl).map(([k, l]) => `<li class="li"><label class="li-b" for="vis-${k}">${l}</label><span class="toggle"><input type="checkbox" role="switch" id="vis-${k}" ${a.vis[k] ? 'checked' : ''} data-onchange="agVis" data-id="${a.id}" data-k="${k}"><span></span></span></li>`).join('')}</ul></section><section class="card"><h2>Live preview — agency's view</h2>${agencyReport(a)}</section></div>`,
    learners: dt({ id: 'agl-' + a.id, name: a.name + ' learners', rows: agencyLearners(a.name), cols: [{ k: 'name', l: 'Learner', h: l => `<a href="#a-learner.${l.id}" data-go="a-learner" data-id="${l.id}">${esc(l.name)}</a>` }, { k: 'courses', l: 'Courses', v: l => l.courses.join('; ') }, { k: 'acct', l: 'Account', h: l => chip(l.acct, 'green') }], empty: 'No learners yet' }),
    bundles: `<ul class="list">${ADMIN.bundles.filter(b => b.agency === a.name).map(b => `<li class="li"><div class="li-b"><strong>${esc(b.name)}</strong><span class="small">${b.used}/${b.seats} seats · valid to ${b.validity ? fd(b.validity) : '—'}</span></div>${chip(b.status, b.status === 'Active' ? 'green' : 'amber')}</li>`).join('') || '<li class="small muted">No bundles.</li>'}</ul>`,
    purchases: `<div class="tbl-wrap"><table class="tbl dense"><thead><tr><th>Date</th><th>Item</th><th>Mode</th><th class="r">Amount</th><th>Status</th></tr></thead><tbody>${ADMIN.bundles.filter(b => b.agency === a.name).map(b => `<tr><td>${fd(D(-100))}</td><td>${esc(b.name)}</td><td>${b.mode === 'Customised' ? 'Invoice (offline)' : 'Gateway'}</td><td class="r">${money(b.price, b.cur)}</td><td>${chip('Paid')}</td></tr>`).join('')}</tbody></table></div>`,
    reports: agencyReport(a),
    messages: `<ul class="list">${ADMIN.threads.filter(x => x.party === a.name).map(x => `<li class="li"><div class="li-b"><strong>${esc(x.subject)}</strong></div>${chip(x.status, x.status === 'Open' ? 'amber' : x.status === 'Answered' ? 'blue' : 'grey')}<button class="btn btn-sm" data-go="a-messages" data-id="${x.id}">Open</button></li>`).join('') || '<li class="small muted">No messages.</li>'}</ul>`,
    audit: auditPanel(x => x.entity.includes(a.name)),
  }[t];
  return `${pageA(esc(a.name), a.region, chip(a.status, a.status === 'Active' ? 'green' : 'amber'), [['Agencies', 'a-agencies'], [a.name]])}<div class="note b-grey">${ic('shield')}<div class="small">One agency can never see another's data.</div></div>
  ${subtabs([['profile', 'Profile & contacts'], ['login', 'Login'], ['visibility', 'Report visibility'], ['learners', 'Learners'], ['bundles', 'Bundles & licences'], ['purchases', 'Purchases & invoices'], ['reports', 'Reports'], ['messages', 'Messages'], ['audit', 'Audit']], t, 'a-agencies', a.id)}${body}`;
}
INP.agVis = el => { const a = ADMIN.agencies.find(x => x.id === el.dataset.id); a.vis[el.dataset.k] = el.checked; logA('Agencies', a.name, 'Report visibility', String(!el.checked), String(el.checked), el.dataset.k); render(); toast('Applied immediately.'); };
ACT.agLogin = el => { const a = ADMIN.agencies.find(x => x.id === el.dataset.id), k = el.dataset.a; if (k === 'resend') { toast('Set-password link resent.'); return; } reasonDlg({ title: k === 'email' ? 'Change login email' : 'Deactivate agency login', ok: k === 'email' ? 'Change login email' : 'Deactivate login', danger: k === 'deactivate', extra: k === 'email' ? `<div class="field"><label for="ne">New email</label><input class="input" id="ne" value="${esc(a.login)}"></div>` : '', onOk: r => { if (k === 'email') a.login = $('#ne').value; else a.loginStatus = 'Deactivated'; logA('Agencies', a.name, k === 'email' ? 'Login email changed' : 'Login deactivated', '—', k === 'email' ? a.login : 'Deactivated', r); render(); } }); };

/* ---------- 6.18 Bundles & Licences ---------- */
SCREENS['a-bundles'] = (p) => {
  const t = p.tab || 'list';
  const st = subtabs([['list', 'Bundles'], ['ledger', 'Licence ledger'], ['expiring', 'Expiring bundles']], t, 'a-bundles');
  const head = pageA('Bundles & Licences', 'Bundle or agency-level validity overrides the course default.', `<button class="btn btn-primary" data-act="newBundle">${ic('plus', 15)}Create bundle</button>`);
  if (t === 'ledger') return head + st + dt({ id: 'ledger', name: 'Licence ledger', rows: ADMIN.ledger.map((l, k) => ({ ...l, id: 'L' + k })), filters: [{ k: 'a', l: 'Agency', get: l => l.agency }, { k: 'k', l: 'Type', get: l => l.kind, opts: ['Credit', 'Debit'] }], cols: [{ k: 'at', l: 'Date', h: l => fd(l.at), s: l => l.at }, { k: 'agency', l: 'Agency' }, { k: 'bundle', l: 'Bundle', h: l => `<span class="mono">${l.bundle}</span>` }, { k: 'kind', l: 'Credit / debit', h: l => chip(l.kind, l.kind === 'Credit' ? 'green' : 'blue') }, { k: 'qty', l: 'Seats', r: 1 }, { k: 'note', l: 'Reason', h: l => `<span class="small">${esc(l.note)}</span>` }] }) + `<p class="small">Totals by bundle: ${ADMIN.bundles.map(b => `${b.id} ${b.seats}/${b.used}/${b.seats - b.used}`).join(' · ')} (total/used/remaining)</p>`;
  if (t === 'expiring') return head + st + `<ul class="list">${ADMIN.bundles.filter(b => b.validity && daysTo(b.validity) <= 30).map(b => `<li class="li"><div class="li-b"><strong>${esc(b.name)}</strong><span class="small">${esc(b.agency)} · ${daysTo(b.validity) < 0 ? 'expired ' + fd(b.validity) : 'expires ' + fd(b.validity) + ' (in ' + daysTo(b.validity) + ' days)'} · ${b.seats - b.used} seats left</span></div>${chip('Agency notified', 'blue')}</li>`).join('')}</ul>`;
  return head + st + dt({ id: 'bundles', name: 'Bundles', rows: ADMIN.bundles, cols: [{ k: 'name', l: 'Bundle', h: b => `<strong>${esc(b.name)}</strong><div class="xs mono muted">${b.id}</div>` }, { k: 'courses', l: 'Included courses', h: b => `<span class="small">${esc(b.courses.join('; '))}</span>`, v: b => b.courses.join() }, { k: 'seats', l: 'Seats', h: b => `${b.used}/${b.seats}`, s: b => b.seats }, { k: 'validity', l: 'Validity', h: b => b.validity ? fd(b.validity) : 'Course default', s: b => b.validity || '' }, { k: 'mode', l: 'Pricing mode' }, { k: 'price', l: 'Price', h: b => money(b.price, b.cur), s: b => b.price }, { k: 'avail', l: 'Availability', h: b => b.avail === 'Global' ? 'Global' : esc(b.agency) }, { k: 'status', l: 'Status', h: b => chip(b.status, { Active: 'green', 'Pending approval': 'amber', Expired: 'grey' }[b.status]) + (b.belowFloor ? ` <span class="xs">publish blocked</span>` : '') }], filters: [{ k: 's', l: 'Status', get: b => b.status }] });
};
ACT.newBundle = () => openModal({ title: 'Create bundle', size: 'lg', body: `<div class="form-grid"><div class="field full"><label for="nbn">Name</label><input class="input" id="nbn" value="Harbour refresher 2027"></div><div class="field full"><span class="lbl">Courses</span><div class="row">${ADMIN.courses.filter(c => c.status === 'Published').slice(0, 5).map((c, k) => `<label class="check small"><input type="checkbox" class="nb-c" value="${c.gbp}" ${k < 2 ? 'checked' : ''} data-onchange="bundleCalc">${esc(c.title)}</label>`).join('')}</div></div><div class="field"><label for="nbs">Seats</label><input class="input" id="nbs" type="number" value="20" data-oninput="bundleCalc"></div><div class="field"><label for="nbv">Validity</label><input class="input" id="nbv" type="date" value="${D(365).slice(0, 10)}"></div><div class="field"><label for="nbm">Pricing mode</label><select class="select" id="nbm" data-onchange="bundleCalc"><option value="auto">Automatic (sum minus discount)</option><option value="custom">Customised (negotiated)</option></select></div><div class="field"><label for="nbd">Discount % / negotiated price (GBP)</label><input class="input" id="nbd" value="15" data-oninput="bundleCalc"></div><div class="field"><label for="nba">Availability</label><select class="select" id="nba"><option>Global</option>${ADMIN.agencies.map(a => `<option>${a.name}</option>`).join('')}</select></div><div class="field full"><label for="nbdesc">Description</label><textarea class="textarea" id="nbdesc"></textarea></div></div><div id="nb-out"></div>`, onOpen: () => INP.bundleCalc(), actions: [{ label: 'Cancel' }, { label: 'Save bundle', cls: 'btn-primary', fn: () => { const calc = bundleCalc(); const id = 'BN-0' + (ADMIN.bundles.length + 1); ADMIN.bundles.unshift({ id, name: mval('#nbn'), agency: mval('#nba') === 'Global' ? '—' : mval('#nba'), courses: ['Selected courses'], seats: +mval('#nbs'), used: 0, validity: new Date(mval('#nbv')).toISOString(), mode: calc.mode, price: calc.price, cur: 'GBP', avail: mval('#nba') === 'Global' ? 'Global' : 'Specific agencies', status: calc.below ? 'Pending approval' : 'Active', belowFloor: calc.below }); if (calc.below) { ADMIN.queue.unshift({ id: 'AQ-' + (1040 + ADMIN.queue.length), type: 'Bundle price below minimum', raisedBy: ADMIN.me.name, raised: now().toISOString(), status: 'Pending', first: 'Owen Price', related: [mval('#nba') + ' · ' + id, 'a-bundles'], amount: calc.price, cur: 'GBP', reason: 'Negotiated price', notes: [], history: [[ADMIN.me.name, now().toISOString(), 'Raised', '']], data: { floor: calc.floor, requested: calc.price, bundle: id } }); if (isSA()) { const it = ADMIN.queue[0]; reasonDlg({ title: 'Below-minimum price — ' + id, ok: 'Apply price', label: 'Reason (required)', onOk: rr => { it.reason = rr; saApply(it, rr); const bb = ADMIN.bundles.find(x => x.id === id); if (bb) { bb.status = 'Active'; bb.belowFloor = false; } toast('Below-minimum price applied — no approval required for the Super Administrator.'); render(); } }); } else toast('Below the minimum price — approval requested. Publishing is blocked until approved.', 'info'); } else toast('Bundle saved.'); render(); } }] });
function bundleCalc() { const sum = $$('.nb-c:checked').reduce((a, x) => a + +x.value, 0) * (+$('#nbs').value || 0), mode = $('#nbm').value, d = +$('#nbd').value || 0; const price = mode === 'auto' ? Math.round(sum * (1 - d / 100)) : d, floor = Math.round(sum * 0.8), below = price < floor; return { sum, price, floor, below, mode: mode === 'auto' ? `Automatic (−${d}%)` : 'Customised' }; }
INP.bundleCalc = () => { const c = bundleCalc(); $('#nb-out').innerHTML = `<p>List total ${money(c.sum, 'GBP')} · <strong>Bundle price ${money(c.price, 'GBP')}</strong> · minimum ${money(c.floor, 'GBP')}</p>${c.below ? `<div class="note b-amber">${ic('alert')}<div class="small"><strong>Below the minimum price — requires approval.</strong> Saving raises an Approvals Queue item. Publishing is blocked until it's approved.</div></div>` : ''}`; };

